package com.kareem.ntake
import android.content.*;import android.database.sqlite.*;import kotlinx.coroutines.flow.*
data class Note(val id:Long,val title:String,val body:String,val source:String,val createdAt:Long,val status:String="READY",val tags:String="",val summary:String="",val followUp:Boolean=false,val dueAt:Long?=null)
class NoteDb(c:Context):SQLiteOpenHelper(c,"ntake.db",null,1){override fun onCreate(db:SQLiteDatabase){db.execSQL("CREATE TABLE notes(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT NOT NULL,source TEXT NOT NULL,createdAt INTEGER NOT NULL,status TEXT NOT NULL,tags TEXT NOT NULL,summary TEXT NOT NULL,followUp INTEGER NOT NULL DEFAULT 0,dueAt INTEGER)");db.execSQL("CREATE INDEX idx_notes_created ON notes(createdAt DESC)")}override fun onUpgrade(db:SQLiteDatabase,o:Int,n:Int){}}
class NoteRepository(c:Context){private val db=NoteDb(c);private val _notes=MutableStateFlow<List<Note>>(emptyList());val notes=_notes.asStateFlow();init{refresh()}@Synchronized fun add(title:String,body:String,source:String,tags:String="",summary:String="",followUp:Boolean=false,dueAt:Long?=null):Long{val v=ContentValues().apply{put("title",title);put("body",body);put("source",source);put("createdAt",System.currentTimeMillis());put("status","READY");put("tags",tags);put("summary",summary);put("followUp",if(followUp)1 else 0);if(dueAt!=null)put("dueAt",dueAt)};val id=db.writableDatabase.insertOrThrow("notes",null,v);refresh();return id}@Synchronized fun setResolved(id:Long){db.writableDatabase.execSQL("UPDATE notes SET status='RESOLVED' WHERE id=?",arrayOf(id));refresh()}@Synchronized fun search(q:String):List<Note>{if(q.isBlank())return _notes.value;val n="%"+q.trim()+"%";return query("SELECT * FROM notes WHERE title LIKE ? OR body LIKE ? OR tags LIKE ? OR summary LIKE ? ORDER BY createdAt DESC",arrayOf(n,n,n,n))}@Synchronized fun refresh(){_notes.value=query("SELECT * FROM notes ORDER BY createdAt DESC",emptyArray())}private fun query(sql:String,args:Array<String>):List<Note>{val out=mutableListOf<Note>();db.readableDatabase.rawQuery(sql,args).use{c->while(c.moveToNext())out+=Note(c.getLong(0),c.getString(1),c.getString(2),c.getString(3),c.getLong(4),c.getString(5),c.getString(6),c.getString(7),c.getInt(8)==1,if(c.isNull(9))null else c.getLong(9))};return out}}